// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/setup/check", wrapper.CheckSetup)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/setup/database", wrapper.SetupDatabase)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/setup/admin", wrapper.SetupAdmin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/auth/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/scopes", wrapper.ListScopes)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/scopes/{id}", wrapper.DeleteScope)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/scopes/{id}", wrapper.GetScope)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/scopes/{id}", wrapper.RenameScope)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/scopes/{id}/enrollment", wrapper.GetEnrollment)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/scopes/{id}/enrollment", wrapper.NewEnrollment)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/hosts/{id}/agent", wrapper.RevokeAgent)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/environments", wrapper.CreateEnvironment)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/hosts/{id}/environment", wrapper.SetHostEnvironment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/changes", wrapper.ListChanges)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/config", wrapper.GetConfig)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/settings", wrapper.SetSetting)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/updates", wrapper.GetUpdates)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/updates", wrapper.CheckUpdates)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/hub/update", wrapper.UpdateHub)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/hosts/{id}/update", wrapper.UpdateHost)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/scopes/{id}/update", wrapper.UpdateScope)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/hosts", wrapper.ListHosts)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/hosts/{id}", wrapper.GetHost)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/hosts/{id}/series", wrapper.GetHostSeries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/filesystems/{id}/series", wrapper.GetFilesystemSeries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/containers/{id}", wrapper.GetContainer)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/containers/{id}/series", wrapper.GetContainerSeries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/events", wrapper.ListEvents)

	return m
}

