// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Log in
	// (POST /api/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Log out
	// (POST /api/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe Who is logged in
	// (GET /api/auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListChanges The history of an object
	// (GET /api/changes)
	ListChanges(ctx context.Context, request ListChangesRequestObject) (ListChangesResponseObject, error)
	// GetConfig The effective settings of an object, and where each comes from
	// (GET /api/config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// GetContainer A container
	// (GET /api/containers/{id})
	GetContainer(ctx context.Context, request GetContainerRequestObject) (GetContainerResponseObject, error)
	// GetContainerSeries A container's usage over time
	// (GET /api/containers/{id}/series)
	GetContainerSeries(ctx context.Context, request GetContainerSeriesRequestObject) (GetContainerSeriesResponseObject, error)
	// CreateEnvironment Create an environment, and its customer and project if needed
	// (POST /api/environments)
	CreateEnvironment(ctx context.Context, request CreateEnvironmentRequestObject) (CreateEnvironmentResponseObject, error)
	// ListEvents What happened to an object
	// (GET /api/events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// GetFilesystemSeries A filesystem's usage over time
	// (GET /api/filesystems/{id}/series)
	GetFilesystemSeries(ctx context.Context, request GetFilesystemSeriesRequestObject) (GetFilesystemSeriesResponseObject, error)
	// GetHealth Whether the hub runs, and how
	// (GET /api/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListHosts All hosts, with their latest reading
	// (GET /api/hosts)
	ListHosts(ctx context.Context, request ListHostsRequestObject) (ListHostsResponseObject, error)
	// GetHost A host, its filesystems and its containers
	// (GET /api/hosts/{id})
	GetHost(ctx context.Context, request GetHostRequestObject) (GetHostResponseObject, error)
	// RevokeAgent Revoke the host's agent credential and disconnect it
	// (DELETE /api/hosts/{id}/agent)
	RevokeAgent(ctx context.Context, request RevokeAgentRequestObject) (RevokeAgentResponseObject, error)
	// SetHostEnvironment Put a host into an environment, or take it out of all
	// (PUT /api/hosts/{id}/environment)
	SetHostEnvironment(ctx context.Context, request SetHostEnvironmentRequestObject) (SetHostEnvironmentResponseObject, error)
	// GetHostSeries A host's readings over time
	// (GET /api/hosts/{id}/series)
	GetHostSeries(ctx context.Context, request GetHostSeriesRequestObject) (GetHostSeriesResponseObject, error)
	// UpdateHost Ask a host's agent to update to the newest release
	// (POST /api/hosts/{id}/update)
	UpdateHost(ctx context.Context, request UpdateHostRequestObject) (UpdateHostResponseObject, error)
	// UpdateHub Update the hub to the newest release
	// (POST /api/hub/update)
	UpdateHub(ctx context.Context, request UpdateHubRequestObject) (UpdateHubResponseObject, error)
	// ListScopes The tree of customers, projects and environments
	// (GET /api/scopes)
	ListScopes(ctx context.Context, request ListScopesRequestObject) (ListScopesResponseObject, error)
	// DeleteScope Delete a scope that is empty
	// (DELETE /api/scopes/{id})
	DeleteScope(ctx context.Context, request DeleteScopeRequestObject) (DeleteScopeResponseObject, error)
	// GetScope A customer, project or environment
	// (GET /api/scopes/{id})
	GetScope(ctx context.Context, request GetScopeRequestObject) (GetScopeResponseObject, error)
	// RenameScope Rename a scope; its key stays
	// (PATCH /api/scopes/{id})
	RenameScope(ctx context.Context, request RenameScopeRequestObject) (RenameScopeResponseObject, error)
	// GetEnrollment An environment's enrollment token, for the install commands
	// (GET /api/scopes/{id}/enrollment)
	GetEnrollment(ctx context.Context, request GetEnrollmentRequestObject) (GetEnrollmentResponseObject, error)
	// NewEnrollment Make a new enrollment token for an environment
	// (POST /api/scopes/{id}/enrollment)
	NewEnrollment(ctx context.Context, request NewEnrollmentRequestObject) (NewEnrollmentResponseObject, error)
	// UpdateScope Ask every connected agent below a scope to update
	// (POST /api/scopes/{id}/update)
	UpdateScope(ctx context.Context, request UpdateScopeRequestObject) (UpdateScopeResponseObject, error)
	// SetSetting Set a setting on an object, or unset it with null
	// (PUT /api/settings)
	SetSetting(ctx context.Context, request SetSettingRequestObject) (SetSettingResponseObject, error)
	// SetupAdmin Create the first admin, the last step of setup
	// (POST /api/setup/admin)
	SetupAdmin(ctx context.Context, request SetupAdminRequestObject) (SetupAdminResponseObject, error)
	// CheckSetup Whether a setup link is the current one, and what setup needs next
	// (POST /api/setup/check)
	CheckSetup(ctx context.Context, request CheckSetupRequestObject) (CheckSetupResponseObject, error)
	// SetupDatabase Choose the database, the first step of setup
	// (POST /api/setup/database)
	SetupDatabase(ctx context.Context, request SetupDatabaseRequestObject) (SetupDatabaseResponseObject, error)
	// GetUpdates The hub's version and the newest release
	// (GET /api/updates)
	GetUpdates(ctx context.Context, request GetUpdatesRequestObject) (GetUpdatesResponseObject, error)
	// CheckUpdates Look for a newer release now, instead of at the next check
	// (POST /api/updates)
	CheckUpdates(ctx context.Context, request CheckUpdatesRequestObject) (CheckUpdatesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

